input.command:
cd /private/tmp/live-spec-morning/wt && for f in register-judge-collect.sh register-judge-report.sh chat-law-hook.sh; do echo "--- $f"; if [ -f ~/.claude/hooks/$f ]; then shasum -a 256 ~/.claude/hooks/$f hooks/$f; else echo "NOT INSTALLED"; fi; done; echo "=== settings.json hooks ==="; python3 -c "
import json,os
p=os.path.expanduser('~/.claude/settings.json')
s=json.load(open(p))
for ev,arr in s.get('hooks',{}).items():
    for e in arr:
        for h in e.get('hooks',[]):
            print(ev, '|', h.get('command'))
"

